// --- inputs from the lesson ---
const uncompressedKB = 500;      // bytes on disk drive parse/compile
const gzipKB = 160;              // ~ what actually transfers over 4G
const linkMbps = 1.6;            // mobile 4G link
const parseRateKBps = 300;       // mid-range Android: 200-400 KB/sec
const compileMs = 300;          // lesson figure
const executeMs = 400;          // lesson figure

// download: gzip bytes over the link (8 bits per byte)
const downloadMs = Math.round((gzipKB * 8) / linkMbps);
// parse: V8 walks every DECOMPRESSED byte
const parseMs = Math.round((uncompressedKB / parseRateKBps) * 1000);
const ttiMs = downloadMs + parseMs + compileMs + executeMs;

console.log('download ms:', downloadMs);
console.log('parse ms:', parseMs);
console.log('compile ms:', compileMs);
console.log('execute ms:', executeMs);
console.log('TTI ms:', ttiMs);
console.log('Note: switching gzip->brotli shrinks ONLY downloadMs; parse/compile are set by uncompressedKB.');

