function overParseBudget(chunks, budgetKB){
  // chunks: [{ name, uncompressedKB, gzipKB }]
  let total = 0;
  for (const c of chunks) {
    total += c.gzipKB;        // what the engine parses
  }
  return total > budgetKB;
}

tasks.verify:
const chunks=[{name:'vendor',uncompressedKB:380,gzipKB:120},{name:'route',uncompressedKB:140,gzipKB:48}];
const over = overParseBudget(chunks, 450);
const under = overParseBudget([{name:'a',uncompressedKB:200,gzipKB:70}], 450);
const ok = over === true && under === false;
console.log(ok ? 'PASS' : 'FAIL over='+over+' under='+under);

