// CI: fail the build if bundles are too big
const BUDGET_KB = 200;

function checkBudget(stats) {
  let biggest = 0;
  for (const asset of stats.assets) {
    const kb = asset.size / 1000;
    if (kb > biggest) biggest = kb;
  }
  if (biggest > BUDGET_KB) {
    console.warn('bundle over budget: ' + biggest + ' KB');
  }
  return true;
}
